/* Final workbench interaction layer: it only changes the presentation and preserves the existing segment data contract. */
(function installCompactAssemblyWorkspace(){
  const typeColors={fresh:'#6ea7bd',return:'#849aa4',mix:'#7591a0',supply:'#6c9aa4',primary:'#8aa9a8',medium:'#739eac',high:'#8c9fbd',coil:'#4b9bb8',heat:'#cf8e48',humid:'#58a7c4',fan:'#788e9d',silencer:'#88979d',access:'#9aa9ad',empty:'#aebcc0'};
  const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
  const thumb=(type,name)=>{const color=typeColors[type]||'#7799a4';let part='<path d="M7 9H45V35H7Z" fill="#eaf3f4" stroke="#3e606b" stroke-width="2"/>';if(['primary','medium','high'].includes(type)){const fins=Array.from({length:type==='high'?7:5},(_,i)=>`<path d="M${12+i*5} 11V33" stroke="${type==='primary'?'#8aa64b':type==='medium'?'#4b9fb2':'#7a75ad'}" stroke-width="3"/>`).join('');part+=fins+'<path d="M9 12H43M9 32H43" stroke="#5c7780" stroke-width="1"/>'}else if(['coil','heat'].includes(type)){const coil=Array.from({length:5},(_,i)=>`<path d="M12 ${12+i*5}H40" stroke="${type==='heat'?'#cf7b3e':'#318fb2'}" stroke-width="2.5"/>`).join('');part+=coil+'<path d="M16 10V35M36 10V35" stroke="#68818a" stroke-width="1.4"/>'}else if(type==='fan'){part+='<circle cx="26" cy="22" r="12" fill="#dce7e9" stroke="#566f78" stroke-width="2"/><path d="M26 10Q36 17 28 22Q36 29 26 34Q16 29 24 22Q16 17 26 10Z" fill="#6b8994"/><circle cx="26" cy="22" r="3" fill="#355862"/>'}else if(type==='humid'){part+='<path d="M26 9C20 17 17 20 17 25A9 9 0 0035 25C35 20 32 17 26 9Z" fill="#5bb8ce" stroke="#3f8294" stroke-width="1.5"/><path d="M11 32H41" stroke="#6e8992" stroke-width="2"/>'}else if(type==='silencer'){part+='<path d="M13 11V33M20 11V33M27 11V33M34 11V33M41 11V33" stroke="#778d94" stroke-width="3"/><path d="M10 12H43M10 32H43" stroke="#c3d4d8" stroke-width="1"/>'}else if(type==='access'||type==='empty'){part+='<rect x="13" y="10" width="26" height="24" fill="#f7fbfb" stroke="#69838c" stroke-width="1.6"/><circle cx="35" cy="23" r="1.8" fill="#ba7e39"/>'}else if(type==='mix'){part+='<path d="M10 15H29M22 10L29 15L22 20M42 29H23M30 24L23 29L30 34" fill="none" stroke="#52899b" stroke-width="2.5"/>'}else{part+='<path d="M10 22H38M32 15L40 22L32 29" fill="none" stroke="#4f93a8" stroke-width="3"/><path d="M11 12V32" stroke="#81979e" stroke-width="2"/>'}return `<span class="library-thumb" aria-hidden="true"><svg viewBox="0 0 52 42" role="img"><rect width="52" height="42" fill="#edf4f5"/>${part}<path d="M7 36H45" stroke="${color}" stroke-width="2" opacity=".75"/></svg></span><span class="library-label">${esc(name)}</span>`};
  function setup(){
    // The workbench must render from its inline project model even when a
    // direct file:// open cannot load the optional project controller.  The
    // controller only supplies project-management actions; it is not a
    // prerequisite for the segment library, thumbnails, or drag ordering.
    renderPalette=function(){
      $('paletteGroups').innerHTML=library.map(group=>group.items.map(([type,name])=>`<button class="library-item" draggable="true" type="button" data-type="${esc(type)}" data-name="${esc(name)}" aria-label="拖拽 ${esc(name)} 到机组构成区">${thumb(type,name)}</button>`).join('')).join('');
    };
    let insertionPreview=null,insertionIndex=null,pendingLibraryInsertAt=null,librarySelectionBeforeDrag=null;
    const animateSegmentShift=before=>{window.requestAnimationFrame(()=>{$('dropzone').querySelectorAll('.segment').forEach(element=>{const old=before.get(element.dataset.id),next=element.getBoundingClientRect();if(!old)return;const delta=old.left-next.left;if(Math.abs(delta)>1)element.animate([{transform:`translateX(${delta}px)`},{transform:'translateX(0)'}],{duration:180,easing:'cubic-bezier(.2,.72,.25,1)'});});});};
    const clearInsertionPreview=()=>{if(!insertionPreview)return;const before=new Map([...$('dropzone').querySelectorAll('.segment')].map(element=>[element.dataset.id,element.getBoundingClientRect()]));insertionPreview.remove();insertionPreview=null;insertionIndex=null;animateSegmentShift(before);};
    renderSegments=function(){
      normalizeRuntimeSegmentIds();
      const oldPositions=new Map([...$('dropzone').querySelectorAll('.segment')].map(element=>[element.dataset.id,element.getBoundingClientRect()]));
      const total=segments.reduce((sum,segment)=>sum+(Number(segment.length)||0),0);
      $('compositionMeta').textContent=`${segments.length} 段 · ${formalReadonly?'正式项目保存值只读':`总长 ${total} mm`}`;
      const blocks=segments.map((segment,index)=>`<button class="segment ${segment.id===selectedId?'selected':''}" draggable="false" data-id="${esc(segment.id)}" title="${esc(segment.name)} · ${esc(segment.length)} mm"><span class="grip">${formalReadonly?'ID':'⠿'}</span><b>${String(index+1).padStart(2,'0')}<br>${esc(segment.name)}</b></button>`).join('');
      $('dropzone').innerHTML=blocks+(!formalReadonly?'<div class="segment-insert" aria-hidden="true"><b>＋</b><span>拖入<br>功能段</span></div>':'');insertionPreview=null;insertionIndex=null;
      $('statusCount').innerHTML=`功能段 <b>${segments.length}</b>`;$('statusDims').innerHTML=`${formalReadonly?'当前方案段长合计':'示意外形'} <b>${total} mm</b>`;$('statusConfirm').innerHTML=formalReadonly?`来源 <b>已保存项目</b>`:`已确认 <b>${segments.filter(segment=>segment.confirmed).length} / ${segments.length}</b>`;$('statusLocation').textContent=formalReadonly?`${formalInfo.projectName} · ${formalInfo.unitNo} · 只读`:`${projects[selectedProject].units[selectedUnit].no} · 功能段配置`;
      $('dropzone').querySelectorAll('.segment').forEach((element,index)=>{const before=oldPositions.get(element.dataset.id),after=element.getBoundingClientRect();if(before){const delta=before.left-after.left;if(Math.abs(delta)>1){element.animate([{transform:`translateX(${delta}px)`},{transform:'translateX(0)'}],{duration:220,easing:'cubic-bezier(.2,.72,.25,1)'});element.classList.add('reordered');}}else element.classList.add('inserted');if(Number.isInteger(pendingLibraryInsertAt)&&index>pendingLibraryInsertAt){element.animate([{transform:'translateX(82px)',filter:'brightness(1.1)'},{transform:'translateX(0)',filter:'brightness(1)'}],{duration:360,easing:'cubic-bezier(.16,.82,.25,1)'});element.classList.add('reordered');}element.addEventListener('animationend',()=>element.classList.remove('inserted','reordered'),{once:true});element.addEventListener('click',()=>selectSegment(element.dataset.id));element.addEventListener('dragstart',event=>{if(formalReadonly){event.preventDefault();return;}dragState={kind:'segment',id:element.dataset.id};event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',element.dataset.id);element.classList.add('dragging');$('dropzone').dataset.dragging='true';});element.addEventListener('dragend',()=>{element.classList.remove('dragging');delete $('dropzone').dataset.dragging;clearInsertionPreview();});});pendingLibraryInsertAt=null;
    };
    renderInputs=function(){
      const segment=segments.find(item=>item.id===selectedId);$('inputTitle').textContent=segment?`${formalReadonly?'正式项目只读':`${segment.name} · 选型录入`}`:'功能段选型录入';
      if(!segment){$('inputGrid').innerHTML='<span class="view-label">选择机组构成中的功能段后录入选型信息。</span>';$('confirmSegment').disabled=true;return;}
      if(formalReadonly){$('inputGrid').innerHTML=`<section class="segment-form-group"><h3>正式保存信息</h3><div class="segment-form-grid"><span class="view-label">稳定段 ID：${esc(segment.id)}</span><span class="view-label">型号：${esc(segment.model)||'未录入'}</span><span class="view-label">零件 ID：${esc(segment.partRef?.partId)||'未关联'}</span></div></section>`;$('confirmSegment').disabled=true;return;}
      ensureGeometry(segment);const dimensionOptions=[500,600,800];
      $('inputGrid').innerHTML=`<section class="segment-form-group"><h3>基本信息</h3><div class="segment-form-grid"><label class="field"><span>功能段名称</span><input data-field="name" value="${esc(segment.name)}"></label><label class="field"><span>人工选定型号</span><input data-field="model" value="${esc(segment.model)}" placeholder="未填写"></label><label class="field"><span>选型来源 *</span><input data-field="source" value="${esc(segment.source)}" placeholder="未填写"></label></div></section><section class="segment-form-group"><h3>尺寸选择</h3><div class="segment-form-grid"><label class="field"><span>段长 mm *</span><input data-field="length" type="number" min="1" value="${esc(segment.length)}"></label><div class="field"><span>常用段长</span><div class="size-options">${dimensionOptions.map(value=>`<button class="size-option ${Number(segment.length)===value?'active':''}" data-length-option="${value}" type="button">${value}</button>`).join('')}<button class="size-option ${dimensionOptions.includes(Number(segment.length))?'':'active'}" data-length-option="custom" type="button">自定义</button></div></div></div><p class="size-help">箱体宽、高与接口尺寸仍按既有机组条件和当前段输入维护；本处只提供段长常用选项。</p></section><section class="segment-form-group"><h3>性能与接口</h3><div class="segment-form-grid"><label class="field"><span>人工能力 kW</span><input data-field="capacity" value="${esc(segment.capacity)}" placeholder="未填写"></label><label class="field"><span>人工阻力 Pa</span><input data-field="resistance" value="${esc(segment.resistance)}" placeholder="未填写"></label><label class="field"><span>接口名称</span><input data-field="interfaceName" value="${esc(segment.interfaceName)}" placeholder="未填写"></label><label class="field"><span>关联 3D 零件</span><select data-part-ref="true"><option value="">暂不关联</option></select></label></div></section>`;$('confirmSegment').disabled=false;
    };
    const originalRenderAll=renderAll;
    renderAll=function(){renderPalette();renderSegments();renderInputs();renderOutputs();renderView();};
    $('paletteGroups').addEventListener('dragstart',event=>{const item=event.target.closest('.library-item');if(!item)return;if(formalReadonly){event.preventDefault();dragState=null;return;}librarySelectionBeforeDrag=selectedId;selectedId=null;$('dropzone').querySelectorAll('.segment.selected').forEach(card=>card.classList.remove('selected'));renderInputs();renderOutputs();dragState={kind:'library',type:item.dataset.type,name:item.dataset.name};event.dataTransfer.effectAllowed='copy';event.dataTransfer.setData('text/plain',item.dataset.type);item.classList.add('drag-origin');$('dropzone').dataset.dragging='true';});$('paletteGroups').addEventListener('dragend',event=>{event.target.closest('.library-item')?.classList.remove('drag-origin');delete $('dropzone').dataset.dragging;clearInsertionPreview();clearDropIndicator();if(dragState?.kind==='library'){selectedId=segments.some(segment=>segment.id===librarySelectionBeforeDrag)?librarySelectionBeforeDrag:null;$('dropzone').querySelectorAll('.segment').forEach(card=>card.classList.toggle('selected',card.dataset.id===selectedId));renderInputs();renderOutputs();dragState=null;}librarySelectionBeforeDrag=null;});
    const clearDropIndicator=()=>$('dropzone').querySelectorAll('.drop-before,.drop-after').forEach(element=>element.classList.remove('drop-before','drop-after'));
    const dropTargetFor=event=>{clearDropIndicator();if(event.target.closest('.segment-drag-placeholder')&&insertionIndex!==null)return insertionIndex;const targetElement=event.target.closest('.segment');if(targetElement&&!targetElement.classList.contains('dragging')){const rect=targetElement.getBoundingClientRect(),after=event.clientX>rect.left+rect.width/2;targetElement.classList.add(after?'drop-after':'drop-before');const index=segments.findIndex(segment=>segment.id===targetElement.dataset.id);return index+(after?1:0);}const next=[...$('dropzone').querySelectorAll('.segment:not(.dragging)')].find(card=>event.clientX<card.getBoundingClientRect().left+card.getBoundingClientRect().width/2);return next?segments.findIndex(segment=>segment.id===next.dataset.id):segments.length;};
    const previewInsertionAt=(event,target)=>{if(!dragState||formalReadonly||target===insertionIndex)return;const before=new Map([...$('dropzone').querySelectorAll('.segment')].map(element=>[element.dataset.id,element.getBoundingClientRect()]));if(insertionPreview)insertionPreview.remove();insertionPreview=document.createElement('div');insertionPreview.className='segment-drag-placeholder';insertionPreview.title='释放后插入';insertionPreview.setAttribute('aria-label','释放后插入');const reference=$('dropzone').querySelector('.segment'),normalWidth=reference?parseFloat(getComputedStyle(reference).minWidth):78;insertionPreview.style.flexBasis=`${(normalWidth||78)/2}px`;insertionPreview.innerHTML='<b>＋</b><span>释放<br>插入</span>';const cards=[...$('dropzone').querySelectorAll('.segment')],anchor=cards[target];if(anchor)$('dropzone').insertBefore(insertionPreview,anchor);else $('dropzone').querySelector('.segment-insert')?.before(insertionPreview);insertionIndex=target;animateSegmentShift(before);};
    const commitDrop=target=>{if(!dragState||formalReadonly)return;if(dragState.kind==='library'){const next={id:allocateSegmentId(),type:dragState.type,name:dragState.name,length:500,confirmed:false,model:'',source:'',capacity:'',resistance:''};pendingLibraryInsertAt=target;segments.splice(target,0,next);selectedId=next.id;}else{const from=segments.findIndex(segment=>segment.id===dragState.id);if(from<0)return;const [next]=segments.splice(from,1);let at=target;if(from<at)at--;segments.splice(Math.max(0,at),0,next);selectedId=next.id;}dragState=null;renderSegments();renderInputs();renderOutputs();$('inputNotice').textContent='段序已更新；拖拽结束后正在刷新结构预览。';window.requestAnimationFrame(()=>window.setTimeout(()=>{renderView();$('inputNotice').textContent='段序已更新，结构预览已完成刷新。';},60));};
    $('dropzone').addEventListener('drop',event=>{event.preventDefault();event.stopImmediatePropagation();const target=insertionIndex??dropTargetFor(event);$('dropzone').classList.remove('dragover');delete $('dropzone').dataset.dragging;commitDrop(target);},true);
    let pointerSession=null,suppressClick=false;
    $('dropzone').addEventListener('click',event=>{if(!suppressClick)return;event.preventDefault();event.stopImmediatePropagation();suppressClick=false;},true);
    $('dropzone').addEventListener('pointerdown',event=>{const card=event.target.closest('.segment');if(event.button!==0||!card||formalReadonly)return;const baseMidpoints=[...$('dropzone').querySelectorAll('.segment')].map(item=>{const rect=item.getBoundingClientRect();return rect.left+rect.width/2;});pointerSession={pointerId:event.pointerId,id:card.dataset.id,card,startX:event.clientX,startY:event.clientY,startScrollLeft:$('dropzone').scrollLeft,baseMidpoints,active:false,ghost:null};window.addEventListener('pointermove',movePointer);window.addEventListener('pointerup',endPointer);window.addEventListener('pointercancel',cancelPointer);});
    function pointerTargetFor(session,event){const scrollShift=session.startScrollLeft-$('dropzone').scrollLeft;const index=session.baseMidpoints.findIndex(midpoint=>event.clientX<midpoint+scrollShift);return index<0?segments.length:index;}
    function movePointer(event){const session=pointerSession;if(!session||event.pointerId!==session.pointerId)return;if(!session.active&&Math.hypot(event.clientX-session.startX,event.clientY-session.startY)<6)return;if(!session.active){session.active=true;dragState={kind:'segment',id:session.id};session.card.classList.add('dragging');session.ghost=document.createElement('div');session.ghost.className='segment-pointer-ghost';session.ghost.textContent=segments.find(segment=>segment.id===session.id)?.name||'功能段';document.body.appendChild(session.ghost);$('dropzone').dataset.dragging='true';}event.preventDefault();session.ghost.style.transform=`translate3d(${event.clientX+14}px,${event.clientY+14}px,0)`;const bounds=$('dropzone').getBoundingClientRect();if(event.clientX<bounds.left||event.clientX>bounds.right||event.clientY<bounds.top||event.clientY>bounds.bottom){clearInsertionPreview();return;}previewInsertionAt(event,pointerTargetFor(session,event));}
    function finishPointer(event,commit){const session=pointerSession;if(!session||event.pointerId!==session.pointerId)return;window.removeEventListener('pointermove',movePointer);window.removeEventListener('pointerup',endPointer);window.removeEventListener('pointercancel',cancelPointer);pointerSession=null;if(!session.active)return;event.preventDefault();suppressClick=true;window.setTimeout(()=>{suppressClick=false;},0);session.ghost?.remove();delete $('dropzone').dataset.dragging;const bounds=$('dropzone').getBoundingClientRect(),inside=event.clientX>=bounds.left&&event.clientX<=bounds.right&&event.clientY>=bounds.top&&event.clientY<=bounds.bottom;if(commit&&inside){commitDrop(insertionIndex??dropTargetFor(event));}else{session.card.classList.remove('dragging');dragState=null;clearInsertionPreview();}clearDropIndicator();}
    function endPointer(event){finishPointer(event,true)}function cancelPointer(event){finishPointer(event,false)}
    $('inputGrid').addEventListener('click',event=>{const option=event.target.closest('[data-length-option]');if(!option)return;const segment=segments.find(item=>item.id===selectedId);if(!segment||option.dataset.lengthOption==='custom'){if(option?.dataset.lengthOption==='custom'){$('inputNotice').textContent='可直接在“段长 mm”中录入自定义尺寸。';}return;}segment.length=Number(option.dataset.lengthOption);segment.confirmed=false;renderSegments();renderInputs();renderOutputs();window.requestAnimationFrame(renderView);$('inputNotice').textContent=`已选用 ${segment.length} mm 常用段长，需重新确认本段。`;});
    const originalDragOver=$('dropzone').onDragOver;
    $('dropzone').addEventListener('dragover',event=>{event.preventDefault();event.dataTransfer.dropEffect=dragState?.kind==='library'?'copy':'move';$('dropzone').classList.add('dragover');$('dropzone').dataset.dragging='true';const target=dropTargetFor(event);previewInsertionAt(event,target);});
    $('dropzone').addEventListener('dragleave',event=>{if(!event.currentTarget.contains(event.relatedTarget)){$('dropzone').classList.remove('dragover');clearDropIndicator();clearInsertionPreview();}});
    renderAll();
    window.ahuCompactReady=true;window.dispatchEvent(new Event('ahu-compact-ready'));
  }
  setup();
})();
